 let flowers='';for(let i=0;i<46;i++){const x=45+(i*173)%1000,y=70+(i*89)%850;if(x>330&&x<740&&y<430||x>760&&y>510&&y<850)continue;flowers+=`<g transform="translate(${x} ${y})"><path d="M0 0v15m0-7-5-3" stroke="#99b191" stroke-width="2"/><circle r="5" fill="${i%2?'#e0abb7':'#eee2ba'}"/><circle r="2" fill="#fff4d6"/></g>`}
